'use strict';
const DBNAME='sheraz-survey-pro-01', STORES=['projects','phases','zones','areas','points','surveys','wirs','pointlinks'];let db,activeProject='',page='dashboard',installPrompt=null;
const $=id=>document.getElementById(id), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=x=>Number(x).toLocaleString('en-US',{maximumFractionDigits:3});const id=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2);const toast=s=>{let t=$('toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3300)};
function openDB(){return new Promise((resolve,reject)=>{let r=indexedDB.open(DBNAME,3);r.onupgradeneeded=()=>{let d=r.result;for(let s of STORES)if(!d.objectStoreNames.contains(s)){let st=d.createObjectStore(s,{keyPath:'id'});if(s!=='projects')st.createIndex('projectId','projectId',{unique:false})}};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function operation(store,mode,fn){return new Promise((resolve,reject)=>{let tx=db.transaction(store,mode),req=fn(tx.objectStore(store));tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error||req.error);tx.onabort=()=>reject(tx.error||new Error('Transaction aborted'))})}const all=s=>operation(s,'readonly',st=>st.getAll()),get=(s,k)=>operation(s,'readonly',st=>st.get(k)),put=(s,o)=>operation(s,'readwrite',st=>st.put(o)),del=(s,k)=>operation(s,'readwrite',st=>st.delete(k));
function batchPut(store,rows){return new Promise((resolve,reject)=>{let tx=db.transaction(store,'readwrite'),st=tx.objectStore(store);for(let row of rows)st.put(row);tx.oncomplete=()=>resolve(rows.length);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Batch import aborted'))})}
const local=s=>s.filter(x=>x.projectId===activeProject);let state={projects:[],phases:[],zones:[],areas:[],points:[],surveys:[],wirs:[],pointlinks:[]};async function reload(){for(let s of STORES)state[s]=await all(s);for(let k of Object.keys(refCache))delete refCache[k];if(activeProject&&!state.projects.some(p=>p.id===activeProject))activeProject='';if(!activeProject&&state.projects.length)activeProject=state.projects[0].id;refreshProjects();render()}
function refreshProjects(){let el=$('projectSelect');el.innerHTML='<option value="">No active project</option>'+state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===activeProject?'selected':''}>${esc(p.name)}</option>`).join('')}
function selectOptions(list,placeholder='Select',selected=''){return `<option value="">${esc(placeholder)}</option>`+list.map(x=>`<option value="${esc(x.id)}" ${selected===x.id?'selected':''}>${esc(x.name||x.code)}</option>`).join('')}
function current(){return state.projects.find(x=>x.id===activeProject)}function scoped(s){return local(state[s])}const refCache={};function ref(s,k){if(!k)return undefined;let cache=refCache[s];if(!cache){cache=new Map(state[s].map(x=>[x.id,x]));refCache[s]=cache}return cache.get(k)}function metric(label,value,meta=''){return `<div class="card"><div class="label">${label}</div><div class="metric">${value}</div><div class="meta">${meta}</div></div>`}function empty(msg){return `<div class="empty">${msg}</div>`}function section(title,body,cls='full'){return `<section class="card ${cls}"><div class="heading"><h2>${title}</h2></div>${body}</section>`}
function render(){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const titles={dashboard:'Command Dashboard',projects:'Project Database',hierarchy:'Phase / Zone / Area',points:'Master Grading Points',engineering:'Engineering Quantities',layers:'Layer Control',surveys:'Survey Register',wirs:'WIR Register',gis:'GIS Survey Map',daily:'Daily Survey Reports',progress:'Area Progress',migration:'Alomaier Migration',matching:'Source Point Audit',reconcile:'Verified Links & RL Audit',quality:'Quantity & Survey QA',gantt:'Layer Gantt & Reports',executive:'Executive Dashboard',audit10:'Data Integrity & Performance',settings:'Data & Backup'};$('pageTitle').textContent=titles[page];$('breadcrumb').textContent=page.toUpperCase();$('view').innerHTML=({dashboard:dashboard,projects:projects,hierarchy:hierarchy,points:points,engineering:engineeringPage,layers:layerPage,surveys:surveyPage,wirs:wirPage,gis:gisPage,daily:dailyPage,progress:progressPage,migration:migrationPage,matching:matchingPage,reconcile:reconcilePage,quality:qualityPage,gantt:ganttPage,executive:executivePage,audit10:audit10Page,settings:settings})[page]();bind();bindOperations();bindPhase4();bindPhase5();bindPhase6();bindPhase7();bindPhase8();bindPhase9();bindPhase10()}
function dashboard(){let pts=scoped('points'),ph=scoped('phases'),zo=scoped('zones'),ar=scoped('areas'),p=current(),cut=0,fill=0,missing=0;for(let x of pts){if(!Number.isFinite(x.designRL)||!Number.isFinite(x.nglRL)){missing++;continue}let d=x.designRL-x.nglRL;if(d>0)fill++;else if(d<0)cut++}let byPhase=ph.map(a=>({name:a.name,count:pts.filter(x=>x.phaseId===a.id).length}));let max=Math.max(1,...byPhase.map(x=>x.count));return `<div class="heading"><div><h2>${esc(p?.name||'Welcome to Eng Sheraz Survey Atlas')}</h2><div class="muted small">${p?'Project '+esc(p.code||'—')+' · '+esc(p.status||'Active'):'Create a project to start managing survey records'}</div></div><div class="actions"><button class="btn gold" data-go="points">+ Add Grading Point</button><button class="btn" data-go="projects">Manage Projects</button></div></div><div class="grid">${metric('Master Grading Points',num(pts.length),'IndexedDB records')}${metric('Project Phases',num(ph.length),'Site divisions')}${metric('Zones / Areas',num(zo.length)+' / '+num(ar.length),'Hierarchy records')}${metric('Missing RL Data',num(missing),missing?'Requires review':'No missing RL values')}</div><div class="grid" style="margin-top:16px">${section('Point Classification',`<div class="row" style="justify-content:space-between"><span class="tag">FILL ${fill}</span><span class="tag bad">CUT ${cut}</span><span class="tag warn">LEVEL ${pts.length-fill-cut-missing}</span></div><p class="small muted">Classification only, based on Design RL − NGL RL. No volumes are estimated without verified area weights.</p><div class="bar"><span style="width:${pts.length?100*fill/pts.length:0}%"></span></div>`,'wide')}${section('Points by Phase',byPhase.length?`<div class="chart">${byPhase.map(x=>`<div style="height:${Math.max(2,x.count/max*100)}%" title="${esc(x.name)}: ${x.count}"><span>${esc(x.name.slice(0,8))}</span></div>`).join('')}</div><p class="muted small" style="margin-top:29px">Counts reflect imported and manually entered points.</p>`:empty('Create phases to see project distribution'),'wide')}${section('Engineering Data Quality',`<div class="note">This foundation tracks project structure and source grading-point values. Boundary-clipped area, cut/fill m³, WIR approvals, and 3D/TIN calculations are deliberately not claimed until their calculation engines are validated.</div><div class="heading"><h2>Recent Grading Points</h2></div>${tablePoints(pts.slice(-6).reverse(),false)}`)}</div>`}
function projects(){return `<div class="grid">${section('Create / Edit Project',`<form id="projectForm" class="form"><input type="hidden" name="id"><label>Project Name *<input name="name" required placeholder="Khuzam 4"></label><label>Project Code<input name="code" placeholder="K4"></label><label>Client<input name="client" placeholder="Client / Developer"></label><label>Location<input name="location" placeholder="City / Site"></label><label>Status<select name="status"><option>Active</option><option>Planning</option><option>On Hold</option><option>Completed</option></select></label><label>Coordinate System<input name="crs" placeholder="e.g. UTM Zone 38N"></label><label class="full">Description<textarea name="description" rows="2"></textarea></label><div class="actions"><button class="btn gold" type="submit">Save Project</button><button class="btn" type="reset">Clear</button></div></form>`,'wide')}${section('Project Management',`<p class="muted small">Each project has independent phases, zones, areas and grading points. Use the selector above to switch.</p><div class="note">Project deletion is intentionally disabled in this release to protect survey records.</div>`,'wide')}${section('All Projects',state.projects.length?`<div class="tablewrap"><table><thead><tr><th>Name</th><th>Code</th><th>Client</th><th>Status</th><th>Points</th><th>Actions</th></tr></thead><tbody>${state.projects.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.code)}</td><td>${esc(p.client)}</td><td><span class="tag">${esc(p.status)}</span></td><td>${state.points.filter(x=>x.projectId===p.id).length}</td><td><button class="link" data-activate="${p.id}">Open</button><button class="link" data-edit-project="${p.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:empty('No projects created yet.'))}</div>`}
function hierarchy(){let ph=scoped('phases'),zo=scoped('zones'),ar=scoped('areas');return `<div class="note">Structure: Project → Phase → Zone → Area. Every record keeps a stable internal ID so renaming a phase or zone does not break linked points.</div><div class="grid" style="margin-top:15px">${section('Add Phase',`<form class="form" id="phaseForm"><label>Phase Name *<input name="name" required placeholder="Phase 1"></label><label>Phase Code<input name="code" placeholder="P1"></label><div class="actions"><button class="btn gold">Save Phase</button></div></form>`)}${section('Add Zone',`<form class="form" id="zoneForm"><label>Phase *<select name="phaseId" required>${selectOptions(ph,'Select Phase')}</select></label><label>Zone Name *<input name="name" required placeholder="Zone A"></label><label>Zone Code<input name="code" placeholder="ZA"></label><div class="actions"><button class="btn gold">Save Zone</button></div></form>`)}${section('Add Area',`<form class="form" id="areaForm"><label>Zone *<select name="zoneId" required>${selectOptions(zo,'Select Zone')}</select></label><label>Area Name *<input name="name" required placeholder="Area 01"></label><label>Area Code<input name="code" placeholder="A01"></label><label class="full">Boundary Corners (Easting,Northing per line)<textarea name="boundary" rows="4" placeholder="665956.000,2756163.000\n665966.000,2756163.000\n665966.000,2756173.000"></textarea></label><div class="actions"><button class="btn gold">Save Area</button></div></form>`,'wide')}${section('Hierarchy Register',`<div class="tablewrap"><table><thead><tr><th>Type</th><th>Name</th><th>Parent</th><th>Code</th><th>Points</th><th>Boundary</th></tr></thead><tbody>${ph.map(x=>`<tr><td>Phase</td><td>${esc(x.name)}</td><td>Project</td><td>${esc(x.code)}</td><td>${scoped('points').filter(p=>p.phaseId===x.id).length}</td><td>—</td></tr>`).join('')}${zo.map(x=>`<tr><td>Zone</td><td>${esc(x.name)}</td><td>${esc(ref('phases',x.phaseId)?.name)}</td><td>${esc(x.code)}</td><td>${scoped('points').filter(p=>p.zoneId===x.id).length}</td><td>—</td></tr>`).join('')}${ar.map(x=>`<tr><td>Area</td><td>${esc(x.name)}</td><td>${esc(ref('zones',x.zoneId)?.name)}</td><td>${esc(x.code)}</td><td>${scoped('points').filter(p=>p.areaId===x.id).length}</td><td>${x.boundary?.length||0} corners</td></tr>`).join('')}</tbody></table></div>${!ph.length&&!zo.length&&!ar.length?empty('No phase, zone or area records yet.'):''}`)}</div>`}
function tablePoints(pts,actions=true){return pts.length?`<div class="tablewrap"><table><thead><tr><th>Point No</th><th>Northing</th><th>Easting</th><th>Design RL</th><th>NGL RL</th><th>Difference</th><th>Classification</th><th>Area</th>${actions?'<th>Actions</th>':''}</tr></thead><tbody>${pts.map(p=>{let d=Number.isFinite(p.nglRL)&&Number.isFinite(p.designRL)?p.designRL-p.nglRL:null;return `<tr><td><b>${esc(p.pointNo)}</b></td><td>${num(p.northing)}</td><td>${num(p.easting)}</td><td>${num(p.designRL)}</td><td>${p.nglRL===null?'—':num(p.nglRL)}</td><td>${d===null?'—':num(d)}</td><td><span class="tag ${d===null?'warn':d<0?'bad':''}">${d===null?'MISSING NGL':d>0?'FILL':d<0?'CUT':'LEVEL'}</span></td><td>${esc(ref('areas',p.areaId)?.name||'Unassigned')}</td>${actions?`<td><button class="link" data-edit-point="${p.id}">Edit</button><button class="link dangertext" data-delete-point="${p.id}">Delete</button></td>`:''}</tr>`}).join('')}</tbody></table></div>`:empty('No grading points found for this selection.')}
function points(){let ph=scoped('phases'),zo=scoped('zones'),ar=scoped('areas'),pts=scoped('points');return `<div class="grid">${section('Grading Point Entry',`<form id="pointForm" class="form"><input type="hidden" name="id"><label>Point Number *<input name="pointNo" required placeholder="GP-001"></label><label>Northing *<input name="northing" type="number" step="any" required></label><label>Easting *<input name="easting" type="number" step="any" required></label><label>Design RL *<input name="designRL" type="number" step="any" required></label><label>NGL RL (optional)<input name="nglRL" type="number" step="any" placeholder="Leave blank if missing"></label><label>Phase<select name="phaseId" id="pointPhase">${selectOptions(ph,'Unassigned')}</select></label><label>Zone<select name="zoneId" id="pointZone">${selectOptions(zo,'Unassigned')}</select></label><label>Area<select name="areaId" id="pointArea">${selectOptions(ar,'Unassigned')}</select></label><div class="actions"><button class="btn gold">Save Grading Point</button><button class="btn" type="reset">Clear</button></div></form>`)}${section('Bulk Import / Export',`<p class="muted small">CSV headers: <code>Point No,Northing,Easting,Design RL,NGL RL,Phase,Zone,Area</code>. Import merges by Point No within the active project. Missing NGL remains blank.</p><div class="actions"><label class="btn" style="display:inline-block;cursor:pointer">Import CSV<input type="file" id="csvFile" accept=".csv,text/csv" hidden></label><button class="btn" id="exportCsv">Export Points CSV</button><button class="btn" id="csvTemplate">Download CSV Template</button></div><p id="csvStatus" class="muted small"></p><div class="note">CSV is parsed locally. For imports, use simple UTF-8 CSV and review the preview before committing.</div>`)}${section('Master Points Register',`<div class="filters"><input id="pointSearch" placeholder="Search point number..." value="${esc(pointSearch)}"><select id="filterPhase">${selectOptions(ph,'All Phases',filterPhase)}</select><select id="filterArea">${selectOptions(ar,'All Areas',filterArea)}</select><span class="muted small">${pts.length.toLocaleString()} points total</span></div><div id="pointTable" style="margin-top:14px">${tablePoints(filterPoints())}</div><div class="muted small" style="margin-top:10px">Showing up to 200 records per view for responsive performance. Export includes all.</div>`)}</div>`}
let pointSearch='',filterPhase='',filterArea='';function filterPoints(){return scoped('points').filter(p=>(!pointSearch||p.pointNo.toLowerCase().includes(pointSearch.toLowerCase()))&&(!filterPhase||p.phaseId===filterPhase)&&(!filterArea||p.areaId===filterArea)).slice(0,200)}

function engineeringPage(){let ar=scoped('areas'),pts=scoped('points');return `<div class="note">Engineering preview — boundary-clipped nominal square cells. Use a verified grid spacing and assign points to the correct area. This is not a TIN or certified quantity measurement. Overlapping/missing cells are flagged.</div><div class="grid" style="margin-top:16px">${section('Area Quantity Calculator',`<form id="engForm" class="form"><label>Project Area<select name="areaId" required>${selectOptions(ar,'Select Area')}</select></label><label>Nominal Grid Spacing (m)<input name="spacing" type="number" min="0.01" max="1000" step="any" value="10" required></label><div class="actions"><button class="btn gold">Calculate Cut / Fill</button><button type="button" class="btn" id="engExport" disabled>Export Quantity CSV</button></div></form><div class="note">Uses only points explicitly assigned to the selected area. Missing NGL stays missing; no assumed RL values. Cell area is clipped to the polygon. Quantity totals are estimates.</div>`,'wide')}${section('Calculation Results',`<div id="engResult">${empty('Choose an area with a valid boundary and calculate.')}</div>`,'wide')}</div>`}
let engResult=null;
function calculateEngineering(f){let v=Object.fromEntries(new FormData(f)),area=ref('areas',v.areaId);if(!area||area.projectId!==activeProject)throw Error('Select a valid project area');if(!area.boundary||area.boundary.length<3)throw Error('Area needs at least three boundary corners');let spacing=Number(v.spacing);if(!Number.isFinite(spacing)||spacing<=0)throw Error('Invalid grid spacing');let pts=scoped('points').filter(p=>p.areaId===area.id);if(!pts.length)throw Error('No grading points assigned to this area');let result=SherazEngineering.evaluateArea(area,pts,spacing);engResult={area,result,spacing};let warn=[];if(result.overlap)warn.push('OVERLAPPING CELL COVERAGE — volumes may be overstated.');if(result.coverageRatio<.98)warn.push('INCOMPLETE GRID COVERAGE — quantities may be understated.');if(result.missing)warn.push(result.missing+' clipped points have missing RL data.');if(!warn.length)warn.push('Check survey grid geometry and independently verify before engineering use.');$('engResult').innerHTML=`<div class="grid">${metric('Polygon Area',num(result.boundaryArea)+' m²','Shoelace / triangulation')}${metric('Clipped Cell Area',num(result.coveredArea)+' m²',num(result.coverageRatio*100)+'% polygon coverage')}${metric('Estimated Fill',num(result.fill)+' m³','Design RL − NGL')}${metric('Estimated Cut',num(result.cut)+' m³','NGL RL − Design')}</div><div class="note" style="margin:14px 0">${warn.map(esc).join('<br>')}</div><div class="tablewrap"><table><thead><tr><th>Point</th><th>Clipped m²</th><th>Δ RL (m)</th><th>Fill m³</th><th>Cut m³</th></tr></thead><tbody>${result.rows.slice(0,150).map(r=>`<tr><td>${esc(r.pointNo)}</td><td>${num(r.cellArea)}</td><td>${r.depth===null?'MISSING':num(r.depth)}</td><td>${r.fill===null?'—':num(r.fill)}</td><td>${r.cut===null?'—':num(r.cut)}</td></tr>`).join('')}</tbody></table></div><p class="muted small">${result.rows.length} intersecting points; showing first 150. CSV exports all.</p>`;$('engExport').disabled=false}

function settings(){return `<div class="grid">${section('Local Data Safety',`<p class="muted">Data is stored in your browser’s IndexedDB. It is not automatically uploaded to a server. Deleting browser site data may remove it.</p><div class="actions"><button class="btn gold" id="backup">Download Complete JSON Backup</button><label class="btn" style="cursor:pointer;display:inline-block">Restore JSON Backup<input id="restoreFile" type="file" accept=".json,application/json" hidden></label></div><div class="note" style="margin-top:15px">Restore merges records by their internal IDs. Keep backup files somewhere safe before changing devices or clearing browser data.</div>`,'wide')}${section('Project Database',`<div class="metric">${state.projects.length} Projects</div><p class="muted small">${state.points.length.toLocaleString()} total points across all projects</p><p class="muted small">${state.phases.length} phases · ${state.zones.length} zones · ${state.areas.length} areas</p>`,'wide')}${section('PWA Installation',`<p class="muted">Installable when hosted on HTTPS or localhost. Offline files are cached by the service worker after a successful visit. Opening index.html directly from a ZIP folder does not enable service-worker installation.</p><p class="muted small">No cloud sync or multi-user access is included in Foundation 01.</p>`)}</div>`}
async function saveProject(form){let fd=new FormData(form),x=Object.fromEntries(fd);if(!x.name.trim())throw Error('Project name is required');let old=x.id?await get('projects',x.id):null;x.id=x.id||id();x.createdAt=old?.createdAt||new Date().toISOString();x.updatedAt=new Date().toISOString();await put('projects',x);activeProject=x.id;await reload();toast('Project saved')}
async function saveHierarchy(kind,form){if(!activeProject)throw Error('Create a project first');let v=Object.fromEntries(new FormData(form));if(!v.name?.trim())throw Error('Name required');if(kind==='zones'&&!v.phaseId)throw Error('Select phase');if(kind==='areas'&&!v.zoneId)throw Error('Select zone');let x={...v,id:id(),projectId:activeProject};if(kind==='zones')x.phaseId=v.phaseId;if(kind==='areas'){let zone=ref('zones',v.zoneId);x.phaseId=zone?.phaseId||'';x.boundary=[];if(v.boundary.trim()){let lines=v.boundary.trim().split(/\r?\n/);for(let l of lines){let [e,n]=l.split(',').map(Number);if(!Number.isFinite(e)||!Number.isFinite(n)||l.split(',').length!==2)throw Error('Invalid boundary line: '+l);x.boundary.push([e,n])}if(x.boundary.length<3)throw Error('Boundary requires at least 3 corners')}delete x.boundaryText}await put(kind,x);await reload();toast('Saved '+kind.slice(0,-1))}
async function savePoint(form){if(!activeProject)throw Error('Create a project first');let v=Object.fromEntries(new FormData(form)),n=['northing','easting','designRL'];if(!v.pointNo?.trim()||n.some(k=>v[k].trim()===''||!Number.isFinite(Number(v[k]))))throw Error('Point No, Northing, Easting and Design RL required');if(v.nglRL.trim()&&!Number.isFinite(Number(v.nglRL)))throw Error('Invalid NGL RL');let conflict=scoped('points').find(p=>p.pointNo.toLowerCase()===v.pointNo.trim().toLowerCase()&&p.id!==v.id);if(conflict)throw Error('Point Number already exists in this project');let area=ref('areas',v.areaId),zone=ref('zones',v.zoneId);if(area){v.zoneId=area.zoneId;v.phaseId=area.phaseId}else if(zone)v.phaseId=zone.phaseId;let old=v.id?await get('points',v.id):null;let x={...v,id:v.id||id(),projectId:activeProject,pointNo:v.pointNo.trim(),northing:Number(v.northing),easting:Number(v.easting),designRL:Number(v.designRL),nglRL:v.nglRL.trim()?Number(v.nglRL):null,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};await put('points',x);await reload();toast('Grading point saved')}
function formFill(form,x){for(let [k,v] of Object.entries(x)){let el=form.elements.namedItem(k);if(el&&typeof v!=='object')el.value=v??''}}
function updatePointSelects(){let f=$('pointForm');if(!f)return;let ph=f.elements.phaseId.value,zo=f.elements.zoneId.value;f.elements.zoneId.innerHTML=selectOptions(scoped('zones').filter(x=>!ph||x.phaseId===ph),'Unassigned',zo);if(!scoped('zones').some(x=>x.id===zo&&(!ph||x.phaseId===ph)))zo='';f.elements.areaId.innerHTML=selectOptions(scoped('areas').filter(x=>(!ph||x.phaseId===ph)&&(!zo||x.zoneId===zo)),'Unassigned',f.elements.areaId.value)}
function download(filename,content,type){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}function csvCell(x){let s=String(x??'');return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}function toCSV(rows){return rows.map(r=>r.map(csvCell).join(',')).join('\r\n')}
function parseCSV(text){let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"')quoted=true;else if(c===','){row.push(field);field=''}else if(c==='\n'){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('Unclosed CSV quote');if(field.length||row.length){row.push(field.replace(/\r$/,''));rows.push(row)}return rows}
let pendingCSV=[];async function previewCSV(file){let rows=parseCSV((await file.text()).replace(/^\uFEFF/,''));if(rows.length<2)throw Error('CSV has no data');let header=rows.shift().map(x=>x.toLowerCase().replace(/[^a-z0-9]/g,''));let find=(...names)=>header.findIndex(h=>names.includes(h));let ix=[find('pointno','pointnumber','point'),find('northing','north'),find('easting','east'),find('designrl','design'),find('nglrl','ngl')];if(ix.slice(0,4).some(i=>i<0))throw Error('CSV must include Point No, Northing, Easting and Design RL');let names=['phase','zone','area'].map(n=>find(n));let seen=new Set();pendingCSV=rows.filter(r=>r.some(x=>x.trim())).map((r,j)=>{let pointNo=(r[ix[0]]||'').trim(),n=Number(r[ix[1]]),e=Number(r[ix[2]]),d=Number(r[ix[3]]),ng=ix[4]>=0?(r[ix[4]]||'').trim():'';if(!pointNo||!r[ix[1]]?.trim()||!r[ix[2]]?.trim()||!r[ix[3]]?.trim()||![n,e,d].every(Number.isFinite)||(ng!==''&&!Number.isFinite(Number(ng))))throw Error('Invalid data on CSV row '+(j+2));let key=pointNo.toLowerCase();if(seen.has(key))throw Error('Duplicate Point No in CSV: '+pointNo);seen.add(key);let look=(store,val)=>{let x=(val||'').trim();return scoped(store).find(o=>o.name.toLowerCase()===x.toLowerCase()||o.code?.toLowerCase()===x.toLowerCase())?.id||''};return{pointNo,northing:n,easting:e,designRL:d,nglRL:ng===''?null:Number(ng),phaseId:names[0]>=0?look('phases',r[names[0]]):'',zoneId:names[1]>=0?look('zones',r[names[1]]):'',areaId:names[2]>=0?look('areas',r[names[2]]):''}});let s=$('csvStatus');s.innerHTML=`<b>${pendingCSV.length.toLocaleString()} validated rows</b> · ${pendingCSV.slice(0,4).map(x=>esc(x.pointNo)).join(', ')}<div class="actions" style="margin-top:10px"><button id="confirmCsv" class="btn gold">Confirm Import</button><button id="cancelCsv" class="btn">Cancel</button></div>`;$('confirmCsv').onclick=async()=>{if(!activeProject)return toast('Create a project first');if(!confirm('Import '+pendingCSV.length+' points into the active project? Existing matching Point Nos will be updated.'))return;try{let map=new Map(scoped('points').map(x=>[x.pointNo.toLowerCase(),x]));for(let x of pendingCSV){let old=map.get(x.pointNo.toLowerCase());await put('points',{...old,...x,id:old?.id||id(),projectId:activeProject,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()})}await reload();toast('CSV import completed')}catch(e){toast('Import error: '+e.message)}};$('cancelCsv').onclick=()=>{pendingCSV=[];s.textContent='Import cancelled'}}
function bind(){let ef=$('engForm');if(ef)ef.onsubmit=e=>{e.preventDefault();try{calculateEngineering(ef)}catch(err){toast(err.message)}};let ee=$('engExport');if(ee)ee.onclick=()=>{if(!engResult)return;let {area,result,spacing}=engResult;download('sheraz_quantity_'+(area.code||'area')+'.csv',toCSV([['Area','Spacing m','Point No','Clipped Area m2','Design minus NGL m','Fill m3','Cut m3'],...result.rows.map(r=>[area.name,spacing,r.pointNo,r.cellArea,r.depth??'',r.fill??'',r.cut??''])]),'text/csv')};document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{page=b.dataset.go;render()});document.querySelectorAll('[data-activate]').forEach(b=>b.onclick=async()=>{activeProject=b.dataset.activate;page='dashboard';await reload()});document.querySelectorAll('[data-edit-project]').forEach(b=>b.onclick=()=>{let x=ref('projects',b.dataset.editProject);formFill($('projectForm'),x);window.scrollTo({top:0,behavior:'smooth'})});document.querySelectorAll('[data-edit-point]').forEach(b=>b.onclick=()=>{let x=ref('points',b.dataset.editPoint);formFill($('pointForm'),x);updatePointSelects();formFill($('pointForm'),x);window.scrollTo({top:0,behavior:'smooth'})});document.querySelectorAll('[data-delete-point]').forEach(b=>b.onclick=async()=>{let x=ref('points',b.dataset.deletePoint);if(confirm('Permanently delete grading point '+x.pointNo+'? Download a backup first if needed.')){await del('points',x.id);await reload();toast('Point deleted')}});for(let [id,fn] of [['projectForm',saveProject],['phaseForm',f=>saveHierarchy('phases',f)],['zoneForm',f=>saveHierarchy('zones',f)],['areaForm',f=>saveHierarchy('areas',f)],['pointForm',savePoint]]){let f=$(id);if(f)f.onsubmit=async e=>{e.preventDefault();try{await fn(f)}catch(err){toast(err.message)}}}let f=$('pointForm');if(f){f.elements.phaseId.onchange=()=>{f.elements.zoneId.value='';f.elements.areaId.value='';updatePointSelects()};f.elements.zoneId.onchange=()=>{f.elements.areaId.value='';updatePointSelects()};f.elements.areaId.onchange=()=>{let a=ref('areas',f.elements.areaId.value);if(a){f.elements.phaseId.value=a.phaseId;f.elements.zoneId.innerHTML=selectOptions(scoped('zones').filter(z=>z.phaseId===a.phaseId),'Unassigned',a.zoneId);f.elements.zoneId.value=a.zoneId}}}let search=$('pointSearch');if(search)search.oninput=e=>{pointSearch=e.target.value;$('pointTable').innerHTML=tablePoints(filterPoints());bindPointActions()};let pf=$('filterPhase');if(pf)pf.onchange=e=>{filterPhase=e.target.value;$('pointTable').innerHTML=tablePoints(filterPoints());bindPointActions()};let af=$('filterArea');if(af)af.onchange=e=>{filterArea=e.target.value;$('pointTable').innerHTML=tablePoints(filterPoints());bindPointActions()};let ex=$('exportCsv');if(ex)ex.onclick=()=>download('sheraz_master_points.csv',toCSV([['Point No','Northing','Easting','Design RL','NGL RL','Phase','Zone','Area'],...scoped('points').map(p=>[p.pointNo,p.northing,p.easting,p.designRL,p.nglRL??'',ref('phases',p.phaseId)?.name||'',ref('zones',p.zoneId)?.name||'',ref('areas',p.areaId)?.name||''])]),'text/csv');let temp=$('csvTemplate');if(temp)temp.onclick=()=>download('grading_points_template.csv','Point No,Northing,Easting,Design RL,NGL RL,Phase,Zone,Area\r\n','text/csv');let cf=$('csvFile');if(cf)cf.onchange=async e=>{try{await previewCSV(e.target.files[0])}catch(err){toast(err.message)}};let bk=$('backup');if(bk)bk.onclick=()=>download('sheraz-survey-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({format:'sheraz-survey-foundation',version:1,exportedAt:new Date().toISOString(),data:state},null,2),'application/json');let rf=$('restoreFile');if(rf)rf.onchange=async e=>{try{let v=JSON.parse(await e.target.files[0].text());if(v.format!=='sheraz-survey-foundation'||v.version!==1||!v.data||!['projects','phases','zones','areas','points'].every(s=>Array.isArray(v.data[s])))throw Error('Unsupported backup format');if(!confirm('Merge '+v.data.points.length+' points and '+v.data.projects.length+' projects from backup?'))return;for(let s of STORES)for(let x of (v.data[s]||[])){if(!x.id||typeof x.id!=='string')throw Error('Invalid record ID');await put(s,x)}await reload();toast('Backup restored')}catch(err){toast('Restore failed: '+err.message)}}}
function bindPointActions(){document.querySelectorAll('[data-edit-point]').forEach(b=>b.onclick=()=>{let x=ref('points',b.dataset.editPoint);formFill($('pointForm'),x);window.scrollTo({top:0,behavior:'smooth'})});document.querySelectorAll('[data-delete-point]').forEach(b=>b.onclick=async()=>{let x=ref('points',b.dataset.deletePoint);if(confirm('Delete '+x.pointNo+'?')){await del('points',x.id);await reload()}})}

const layerSettings={thickness:.30,preparation:.30,maxLayers:30,tolerance:.02};
function layerPage(){let pts=scoped('points'),s=scoped('surveys'),fill=pts.filter(p=>Number.isFinite(p.nglRL)&&p.designRL>=p.nglRL-layerSettings.preparation);let complete=fill.filter(p=>{let x=SurveyOps.progress(p,s,layerSettings);return x.rows.length&&x.completed===x.rows.length}).length;return `<div class="grid">${metric('Fill Candidate Points',num(fill.length),'NGL and Design available')}${metric('Verified Final Layers',num(complete),'Based on ACCEPTED surveys only')}${section('Layer Plan Settings',`<form id="layerSettings" class="form"><label>Fill Layer Thickness (m)<input name="thickness" type="number" min=".01" step=".01" value="${layerSettings.thickness}" required></label><label>Preparation below NGL (m)<input name="preparation" type="number" min="0" step=".01" value="${layerSettings.preparation}" required></label><label>Survey Tolerance (m)<input name="tolerance" type="number" min="0" step=".001" value="${layerSettings.tolerance}" required></label><label>Grading Point<select name="pointId" required>${selectOptions(pts.map(p=>({...p,name:p.pointNo})),'Select Point')}</select></label><div class="actions"><button class="btn gold">Calculate Layers</button><button class="btn" type="button" id="layerCSV">Export All Layer Plans CSV</button></div></form><div class="note">Layer 1 starts from NGL minus preparation depth. Previous RL follows the preceding target RL. A latest ACCEPTED survey is required for verified progress; PENDING or REJECTED observations never count.</div>`,'wide')}${section('Layer-by-layer Results',`<div id="layerResult">${empty('Select a grading point to inspect its layer plan.')}</div>`,'wide')}</div>`}
function surveyPage(){let pts=scoped('points'),sv=scoped('surveys').slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<div class="grid">${section('New Survey Observation',`<form id="surveyForm" class="form"><label>Grading Point<select name="pointId" required>${selectOptions(pts.map(p=>({...p,name:p.pointNo})),'Select Point')}</select></label><label>Survey Date<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Actual RL (m)<input name="actualRL" type="number" step=".001" required></label><label>Layer Number<input name="layer" type="number" min="0" max="30" value="0" required></label><label>QA Status<select name="status"><option value="PENDING">PENDING</option><option value="ACCEPTED">ACCEPTED</option><option value="REJECTED">REJECTED</option></select></label><label>WIR Reference<input name="wirRef" placeholder="Optional WIR reference"></label><label class="full">Remarks<textarea name="remarks" rows="2"></textarea></label><div class="actions"><button class="btn gold">Save Survey Record</button><button type="button" class="btn" id="surveyCSV">Export Survey CSV</button></div></form><div class="note">ACCEPTED is a manually recorded status, not proof of external approval. Retain the signed WIR separately.</div>`,'wide')}${section('Survey History',`<div class="tablewrap"><table><thead><tr><th>Date</th><th>Point</th><th>Actual RL</th><th>Layer</th><th>Status</th><th>WIR</th></tr></thead><tbody>${sv.slice(0,200).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(ref('points',x.pointId)?.pointNo||'Unknown')}</td><td>${num(x.actualRL)}</td><td>${esc(x.layer)}</td><td><span class="tag">${esc(x.status)}</span></td><td>${esc(x.wirRef)}</td></tr>`).join('')}</tbody></table></div><p class="muted small">Showing latest 200 records; export includes all ${sv.length}.</p>`,'wide')}</div>`}
function wirPage(){let ws=scoped('wirs').slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<div class="grid">${section('WIR Tracking',`<form id="wirForm" class="form"><label>WIR Reference<input name="reference" required placeholder="WIR-001"></label><label>Date<input name="date" type="date" required value="${new Date().toISOString().slice(0,10)}"></label><label>Area<select name="areaId">${selectOptions(scoped('areas'),'Optional Area')}</select></label><label>Layer Number<input name="layer" type="number" min="0" max="30" value="0" required></label><label>Status<select name="status"><option>SUBMITTED</option><option>APPROVED</option><option>REJECTED</option><option>HOLD</option></select></label><label class="full">Remarks<textarea name="remarks"></textarea></label><div class="actions"><button class="btn gold">Save WIR</button><button type="button" class="btn" id="wirCSV">Export WIR CSV</button></div></form><div class="note">WIR status is manually entered. This module does not provide external approval verification or attachments yet.</div>`,'wide')}${section('WIR Register',`<div class="tablewrap"><table><thead><tr><th>Reference</th><th>Date</th><th>Area</th><th>Layer</th><th>Status</th><th>Remarks</th></tr></thead><tbody>${ws.slice(0,200).map(w=>`<tr><td>${esc(w.reference)}</td><td>${esc(w.date)}</td><td>${esc(ref('areas',w.areaId)?.name)}</td><td>${esc(w.layer)}</td><td>${esc(w.status)}</td><td>${esc(w.remarks)}</td></tr>`).join('')}</tbody></table></div>`,'wide')}</div>`}
function bindOperations(){
 const lf=$('layerSettings');if(lf)lf.onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(lf)),p=ref('points',v.pointId);if(!p)return;for(let k of ['thickness','preparation','tolerance'])layerSettings[k]=Number(v[k]);if(!(layerSettings.thickness>0&&layerSettings.preparation>=0&&layerSettings.tolerance>=0)){toast('Invalid settings');return}let x=SurveyOps.progress(p,scoped('surveys'),layerSettings);$('layerResult').innerHTML=x.error?`<div class="note">${esc(x.error)}</div>`:`<div class="grid">${metric('Planned Layers',x.rows.length,'Maximum 30')}${metric('Verified Layers',x.completed,'Latest ACCEPTED survey')}${metric('Remaining to Design',x.remaining===null?'No accepted survey':num(x.remaining)+' m','Actual RL to Design RL')}</div><div class="tablewrap"><table><thead><tr><th>Layer</th><th>Previous RL</th><th>Target RL</th><th>Thickness</th><th>Progress</th></tr></thead><tbody>${x.rows.map(l=>`<tr><td>${l.layer}</td><td>${num(l.previousRL)}</td><td>${num(l.targetRL)}</td><td>${num(l.thickness)}</td><td>${x.accepted&&x.accepted.actualRL>=l.targetRL-layerSettings.tolerance?'REACHED':'NOT VERIFIED'}</td></tr>`).join('')}</tbody></table></div>`};
 const lc=$('layerCSV');if(lc)lc.onclick=()=>download('layer_plans.csv',toCSV([['Point','Layer','Previous RL','Target RL','Thickness','Latest Accepted RL','Reached'],...scoped('points').flatMap(p=>{let x=SurveyOps.progress(p,scoped('surveys'),layerSettings);return x.rows.map(l=>[p.pointNo,l.layer,l.previousRL,l.targetRL,l.thickness,x.accepted?.actualRL??'',x.accepted&&x.accepted.actualRL>=l.targetRL-layerSettings.tolerance?'YES':'NO'])})]),'text/csv');
 const sf=$('surveyForm');if(sf)sf.onsubmit=async e=>{e.preventDefault();try{if(!activeProject)throw Error('Select a project');let v=Object.fromEntries(new FormData(sf));if(!ref('points',v.pointId)||!Number.isFinite(Number(v.actualRL))||v.actualRL==='')throw Error('Select a point and valid RL');await put('surveys',{...v,id:id(),projectId:activeProject,actualRL:Number(v.actualRL),layer:Number(v.layer),createdAt:new Date().toISOString()});await reload();toast('Survey observation saved')}catch(err){toast(err.message)}};
 const sc=$('surveyCSV');if(sc)sc.onclick=()=>download('survey_register.csv',toCSV([['Date','Point','Actual RL','Layer','Status','WIR','Remarks'],...scoped('surveys').map(x=>[x.date,ref('points',x.pointId)?.pointNo||'',x.actualRL,x.layer,x.status,x.wirRef,x.remarks])]),'text/csv');
 const wf=$('wirForm');if(wf)wf.onsubmit=async e=>{e.preventDefault();try{if(!activeProject)throw Error('Select a project');let v=Object.fromEntries(new FormData(wf));if(!v.reference?.trim())throw Error('Reference required');await put('wirs',{...v,id:id(),projectId:activeProject,layer:Number(v.layer),createdAt:new Date().toISOString()});await reload();toast('WIR record saved')}catch(err){toast(err.message)}};
 const wc=$('wirCSV');if(wc)wc.onclick=()=>download('wir_register.csv',toCSV([['Reference','Date','Area','Layer','Status','Remarks'],...scoped('wirs').map(w=>[w.reference,w.date,ref('areas',w.areaId)?.name||'',w.layer,w.status,w.remarks])]),'text/csv');
}


let mapFilterArea='',mapMode='status',mapZoom=1;
function mapData(){let pts=scoped('points');return mapFilterArea?pts.filter(p=>p.areaId===mapFilterArea):pts}
function gisPage(){let pts=mapData(),areas=scoped('areas');return `<div class="grid">${section('GIS / Coordinate Workspace',`<div class="actions"><label>Area <select id="gisArea"><option value="">All Areas</option>${areas.map(a=>`<option value="${esc(a.id)}" ${mapFilterArea===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Color <select id="gisMode"><option value="status" ${mapMode==='status'?'selected':''}>Cut / Fill</option><option value="qa" ${mapMode==='qa'?'selected':''}>Latest Accepted Survey</option></select></label><button class="btn" id="gisZoomIn">Zoom +</button><button class="btn" id="gisZoomOut">Zoom −</button><button class="btn" id="gisExport">Export Visible Points CSV</button></div><p class="muted small">Engineering coordinate map (Easting / Northing), not a georeferenced satellite basemap. Green = fill or accepted; red = cut; gold = level / pending / no accepted survey. Hover or tap points for details.</p><div id="gisCanvas" class="gisCanvas"></div><div id="gisInfo" class="note">Select a point to inspect its elevations and survey status.</div>`,'wide')}${section('Visible Map Records',`<p class="muted">${pts.length.toLocaleString()} points in selected scope · ${areas.length} areas in project</p><div class="tablewrap" style="max-height:340px">${tablePoints(pts.slice(0,100),false)}</div><p class="small muted">First 100 rows shown. Map may sample points for responsiveness; CSV exports every filtered point.</p>`,'wide')}</div>`}
function mapDraw(){let el=$('gisCanvas');if(!el)return;let pts=mapData().filter(p=>Number.isFinite(p.easting)&&Number.isFinite(p.northing));let boundaries=scoped('areas').filter(a=>!mapFilterArea||a.id===mapFilterArea).map(a=>({a,poly:parseBoundarySafe(a)})).filter(x=>x.poly.length>=3);if(!pts.length&&!boundaries.length){el.innerHTML=empty('Add Easting/Northing points or Area boundary corners to display the map.');return}let xy=pts.map(p=>[p.easting,p.northing]).concat(boundaries.flatMap(x=>x.poly));let minE=Math.min(...xy.map(v=>v[0])),maxE=Math.max(...xy.map(v=>v[0])),minN=Math.min(...xy.map(v=>v[1])),maxN=Math.max(...xy.map(v=>v[1]));let span=Math.max(maxE-minE,maxN-minN,1)/mapZoom,cx=(minE+maxE)/2,cy=(minN+maxN)/2;let X=e=>500+(e-cx)*880/span,Y=n=>340-(n-cy)*580/span;let latest=mapMode==='qa'?scoped('surveys'):[],max=pts.length>3500?3500:pts.length,stride=Math.max(1,Math.ceil(pts.length/max));let svg='<svg viewBox="0 0 1000 680" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Grading points coordinate map"><rect width="1000" height="680" fill="#091c1d"/>';for(let i=0;i<11;i++){let v=i*100;svg+=`<path d="M ${v} 0 V 680 M 0 ${i*68} H 1000" stroke="#24423d" stroke-width=".7"/>`}for(let {a,poly} of boundaries){svg+=`<polygon points="${poly.map(v=>X(v[0])+','+Y(v[1])).join(' ')}" fill="#e5c17b" fill-opacity=".08" stroke="#e5c17b" stroke-width="2"><title>${esc(a.name)}</title></polygon>`}let rendered=[];for(let i=0;i<pts.length;i+=stride){let p=pts[i],accepted=mapMode==='qa'?SurveyOps.latestAccepted(latest,p.id):null,color=mapMode==='qa'?(accepted?'#55d7a0':'#d9b767'):(Number.isFinite(p.designRL)&&Number.isFinite(p.nglRL)?p.designRL>p.nglRL?'#55d7a0':p.designRL<p.nglRL?'#fb7c80':'#d9b767':'#9caab0');let x=X(p.easting),y=Y(p.northing);if(!Number.isFinite(x+y))continue;svg+=`<circle data-pt="${esc(p.id)}" cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="4" fill="${color}" stroke="#102522" stroke-width=".8"><title>${esc(p.pointNo)} | Design ${p.designRL??'—'} | NGL ${p.nglRL??'—'}</title></circle>`;rendered.push(p)}svg+='<text x="22" y="35" fill="#d8bd7c" font-size="17">N ↑  |  Survey Coordinate Workspace</text><text x="22" y="60" fill="#abc1b7" font-size="13">Showing '+rendered.length+' / '+pts.length+' points · Scale is illustrative</text></svg>';el.innerHTML=svg;el.querySelectorAll('[data-pt]').forEach(c=>c.onclick=()=>{let p=ref('points',c.dataset.pt),a=SurveyOps.latestAccepted(scoped('surveys'),p.id);$('gisInfo').textContent=`${p.pointNo} · E ${p.easting} · N ${p.northing} · Design ${p.designRL??'missing'} · NGL ${p.nglRL??'missing'} · Latest accepted RL ${a?.actualRL??'none'}`})}
function parseBoundarySafe(a){try{let b=a.boundary;if(typeof b==='string')b=JSON.parse(b);if(!Array.isArray(b))return [];return b.map(v=>Array.isArray(v)?[Number(v[0]),Number(v[1])]:[Number(v.easting??v.e),Number(v.northing??v.n)]).filter(v=>v.every(Number.isFinite))}catch{return []}}
let reportDate=new Date().toISOString().slice(0,10);
function dailyRows(){let sv=scoped('surveys').filter(x=>x.date===reportDate),w=scoped('wirs').filter(x=>x.date===reportDate);return {sv,w,accepted:sv.filter(x=>x.status==='ACCEPTED'),rejected:sv.filter(x=>x.status==='REJECTED'),pending:sv.filter(x=>x.status==='PENDING')}}
function dailyPage(){let d=dailyRows(),p=current();return `<div class="grid">${section('Daily Survey Reporting',`<div class="actions"><label>Report Date <input type="date" id="dailyDate" value="${esc(reportDate)}"></label><button class="btn gold" id="dailyPrint">Print / Save PDF</button><button class="btn" id="dailyCSV">Survey CSV</button><button class="btn" id="dailyWIRCSV">WIR CSV</button></div><div id="dailyPrintable"><h2>${esc(p?.name||'No active project')} — Daily Survey Report</h2><p class="muted">Date: ${esc(reportDate)} · Project: ${esc(p?.code||'—')}</p><div class="grid">${metric('Survey Observations',d.sv.length,'All statuses')}${metric('Accepted',d.accepted.length,'Manually recorded')}${metric('Pending / Rejected',d.pending.length+' / '+d.rejected.length,'Requires review')}${metric('WIR Records',d.w.length,'Recorded on selected date')}</div><h3>Survey Observations</h3><div class="tablewrap"><table><thead><tr><th>Point</th><th>Actual RL</th><th>Layer</th><th>Status</th><th>WIR Ref</th></tr></thead><tbody>${d.sv.map(x=>`<tr><td>${esc(ref('points',x.pointId)?.pointNo||'Unknown')}</td><td>${num(x.actualRL)}</td><td>${esc(x.layer)}</td><td>${esc(x.status)}</td><td>${esc(x.wirRef)}</td></tr>`).join('')}</tbody></table></div><h3>WIR Activity</h3><div class="tablewrap"><table><thead><tr><th>Reference</th><th>Area</th><th>Layer</th><th>Status</th></tr></thead><tbody>${d.w.map(x=>`<tr><td>${esc(x.reference)}</td><td>${esc(ref('areas',x.areaId)?.name)}</td><td>${esc(x.layer)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div><p class="note">Report uses locally entered records only. Acceptance and WIR status are not externally verified.</p></div>`,'wide')}</div>`}
function bindPhase4(){if(page==='gis'){let a=$('gisArea'),m=$('gisMode');a.onchange=()=>{mapFilterArea=a.value;render()};m.onchange=()=>{mapMode=m.value;mapDraw()};$('gisZoomIn').onclick=()=>{mapZoom=Math.min(10,mapZoom*1.5);mapDraw()};$('gisZoomOut').onclick=()=>{mapZoom=Math.max(.5,mapZoom/1.5);mapDraw()};$('gisExport').onclick=()=>download('gis_points.csv',toCSV([['Point','Easting','Northing','Design RL','NGL RL','Area'],...mapData().map(p=>[p.pointNo,p.easting,p.northing,p.designRL,p.nglRL??'',ref('areas',p.areaId)?.name||''])]),'text/csv');mapDraw()}
if(page==='daily'){$('dailyDate').onchange=e=>{reportDate=e.target.value;render()};$('dailyPrint').onclick=()=>window.print();$('dailyCSV').onclick=()=>{let d=dailyRows();download('daily_surveys_'+reportDate+'.csv',toCSV([['Date','Point','Actual RL','Layer','Status','WIR','Remarks'],...d.sv.map(x=>[x.date,ref('points',x.pointId)?.pointNo||'',x.actualRL,x.layer,x.status,x.wirRef,x.remarks])]),'text/csv')};$('dailyWIRCSV').onclick=()=>{let d=dailyRows();download('daily_wirs_'+reportDate+'.csv',toCSV([['Date','Reference','Area','Layer','Status','Remarks'],...d.w.map(x=>[x.date,x.reference,ref('areas',x.areaId)?.name||'',x.layer,x.status,x.remarks])]),'text/csv')}}}


let sourceArchive=null, sourcePhase='P1', sourceAreaIndex='0',sourceBatch=500,sourcePreview=[];
function progressPage(){let areas=scoped('areas'),pts=scoped('points'),surveys=scoped('surveys'),groups=areas.map(a=>{let ps=pts.filter(p=>p.areaId===a.id),eligible=ps.filter(p=>Number.isFinite(p.designRL)&&Number.isFinite(p.nglRL)),complete=eligible.filter(p=>{let r=SurveyOps.progress(p,surveys,layerSettings);return !r.error&&r.rows.length>0&&r.completed===r.rows.length}).length,accepted=eligible.filter(p=>SurveyOps.latestAccepted(surveys,p.id)).length;return {name:a.name,code:a.code,points:ps.length,eligible:eligible.length,complete,accepted,percent:eligible.length?Math.round(100*complete/eligible.length):0}});let total=groups.reduce((a,x)=>a+x.points,0),complete=groups.reduce((a,x)=>a+x.complete,0);return `<div class="grid">${metric('Areas',areas.length,'Project areas')}${metric('Assigned Points',total,'Points with area assignment')}${metric('Verified Final Layers',complete,'Latest ACCEPTED survey')}${metric('Surveys',surveys.length,'All statuses')}${section('Area-wise Layer Progress',`<div class="actions"><button class="btn gold" id="progressCSV">Export Area Progress CSV</button></div><p class="note">Only the latest manually recorded ACCEPTED survey contributes to layer verification. Progress is point-count based, not measured completed volume. Imported historical WIR records do not count as accepted surveys.</p><div class="tablewrap"><table><thead><tr><th>Area</th><th>Points</th><th>RL Complete</th><th>Accepted Surveys</th><th>Final Layer Verified</th><th>Progress</th></tr></thead><tbody>${groups.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.points}</td><td>${x.eligible}</td><td>${x.accepted}</td><td>${x.complete}</td><td><div class="progressTrack"><span style="width:${x.percent}%"></span></div>${x.percent}%</td></tr>`).join('')}</tbody></table></div>`,'wide')}${section('Area Progress Chart',`<div class="areaChart">${groups.slice(0,44).map(x=>`<div class="areaBar"><span title="${esc(x.name)}">${esc(x.code||x.name)}</span><div class="progressTrack"><span style="width:${x.percent}%"></span></div><b>${x.percent}%</b></div>`).join('')}</div>`,'wide')}</div>`}
function migrationPage(){let loaded=!!sourceArchive;return `<div class="grid">${section('ALOMA​​IER Original Project Archive',`<p class="muted">The supplied original file is the data source. Preview it here, then import selected records into the new project database. Import is opt-in and preserves the original archive. First create or select a destination project.</p><div class="actions"><button class="btn gold" id="sourceLoad">Load Original Archive</button><button class="btn gold" id="sourceAll">Import ALL Original Data (97,660 IFC Points + Areas + WIRs)</button><button class="btn" id="sourceAreas" ${!loaded?'disabled':''}>Import Phase / Zone / Area Hierarchy</button><button class="btn" id="sourceWirs" ${!loaded?'disabled':''}>Import Historical WIR Register</button></div><p class="note" id="sourceStatus">${loaded?'Archive loaded. Select the import action you need.':'Click Load Original Archive. File size is approximately 2.5 MB.'}</p>${loaded?`<div class="grid">${metric('Source IFC Points',Object.values(sourceArchive.design.phases).reduce((n,x)=>n+x.e.length,0),'Encoded design grid')}${metric('Source Areas',sourceArchive.areas.length,'Original boundary corners')}${metric('Source WIRs',sourceArchive.wirs.length,'Historical, not verified')}${metric('Source Phases',Object.keys(sourceArchive.design.phases).length,'Original design phases')}</div>`:''}`,'wide')}${section('Selective IFC Design Grid Import',`<p class="note">Import by source phase in limited batches. IFC reference IDs are generated for migration because the encoded grid does not contain original Point No. NGL decoding is checked against the encoded sample length. Missing NGL stays blank. Grid points are not automatically assigned to areas or surveys.</p><form id="sourceGridForm" class="form"><label>Source Phase<select name="phase">${['P1','P2','P3','P4'].map(p=>`<option ${sourcePhase===p?'selected':''}>${p}</option>`).join('')}</select></label><label>Batch Offset<input name="offset" type="number" min="0" value="0" required></label><label>Batch Size<select name="size"><option>100</option><option selected>500</option><option>1000</option><option>2000</option></select></label><div class="actions"><button class="btn" type="button" id="gridSourcePreview">Preview First Records</button><button class="btn gold" type="submit">Import IFC Batch</button></div></form><div id="gridSourceResults">${empty('Load the archive to preview source grid points.')}</div>`,'wide')}${section('Source Area & WIR Preview',`<div id="sourceRegisters">${loaded?`<h3>Areas</h3><div class="tablewrap"><table><thead><tr><th>Code</th><th>Name</th><th>Zone</th><th>Corners</th></tr></thead><tbody>${sourceArchive.areas.map(a=>`<tr><td>${esc(a.k)}</td><td>${esc(a.name)}</td><td>${esc(a.zone)}</td><td>${a.c.length}</td></tr>`).join('')}</tbody></table></div><h3>WIRs</h3><div class="tablewrap"><table><thead><tr><th>Reference</th><th>Date</th><th>Layer</th><th>Observations</th></tr></thead><tbody>${sourceArchive.wirs.map(w=>`<tr><td>${esc(w.cno)}</td><td>${esc(w.date)}</td><td>${esc(w.layer)}</td><td>${w.pts?.length||0}</td></tr>`).join('')}</tbody></table></div>`:empty('Load archive to inspect source areas and WIR records.')}</div>`,'wide')}</div>`}
async function importSourceHierarchy(){if(!activeProject)throw Error('Create or select a project first');let a=sourceArchive,phaseRecords=Object.keys(a.design.phases).map(p=>({id:'alom-phase-'+activeProject+'-'+p,projectId:activeProject,name:'Phase '+p.slice(1),code:p,source:'ALOMA​​IER'}));for(let p of phaseRecords)await put('phases',p);let zones=[...new Set(a.areas.map(x=>x.zone))];for(let z of zones){let zoneId='alom-zone-'+activeProject+'-'+z.replace(/[^a-zA-Z0-9]/g,'_');await put('zones',{id:zoneId,projectId:activeProject,phaseId:phaseRecords[0].id,name:z,code:z,source:'ALOMA​​IER',phaseAssignmentUnverified:true})}for(let ar of a.areas){let zid='alom-zone-'+activeProject+'-'+ar.zone.replace(/[^a-zA-Z0-9]/g,'_');await put('areas',{id:'alom-area-'+activeProject+'-'+ar.k,projectId:activeProject,zoneId:zid,name:ar.name,code:ar.k,boundary:JSON.stringify(ar.c),source:'ALOMA​​IER',sourceAreaM2:ar.m2})}await reload();toast('Imported original hierarchy. Verify zone-to-phase assignments.')}
async function importSourceWIR(){if(!activeProject)throw Error('Create or select a project first');for(let w of sourceArchive.wirs){await put('wirs',{id:'alom-wir-'+activeProject+'-'+w.cno,projectId:activeProject,reference:w.cno,date:w.date,layer:Number(w.layer)||0,status:'IMPORTED_UNVERIFIED',remarks:w.desc||'',source:'ALOMA​​IER',sourcePhase:w.phase,sourceRef:w.ref,sourceObservations:w.pts||[]})}await reload();toast('Historical WIR records imported as unverified')}
function decodeSourceGrid(phase,offset,count){let a=sourceArchive,d=a.design.phases[phase],ng=a.ngl.ph[phase];if(!d)throw Error('Unknown source phase');let raw=atob(ng||''),valid=raw.length===d.e.length*2,rows=[];for(let i=offset;i<Math.min(offset+count,d.e.length);i++){let code=valid?(raw.charCodeAt(2*i)|(raw.charCodeAt(2*i+1)<<8)):65535;rows.push({pointNo:'IFC-'+phase+'-'+String(i+1).padStart(6,'0'),easting:a.design.E0+d.e[i]/10,northing:a.design.N0+d.n_[i]/10,designRL:a.design.Z0+d.z[i]/1000,nglRL:code===65535?null:a.ngl.z0+code*a.ngl.u,phase,sourceIndex:i})}return {rows,valid,total:d.e.length}}
async function importAllSourceData(automatic=false){
 if(!activeProject)throw Error('First create or select a destination project in Project Database');
 if(!sourceArchive){let r=await fetch('./alomaier-source.json');if(!r.ok)throw Error('Original source archive is missing');sourceArchive=await r.json()}
 let expected=Object.values(sourceArchive.design.phases).reduce((n,p)=>n+p.e.length,0);
 if(!automatic && !confirm('Import '+expected.toLocaleString()+' IFC design points, 44 areas, 43 historical WIR records into the selected project? This may take several minutes on mobile. Source WIRs stay UNVERIFIED; IFC reference IDs are generated. Do not close the tab during import.'))return;
 let btn=$('sourceAll'),status=$('sourceStatus');if(btn)btn.disabled=true;
 const update=message=>{if(status)status.textContent=message;const auto=$('atlasAutoStatus');if(auto)auto.textContent=message};
 try{
 update('Importing source Phase / Zone / Area hierarchy...');
 await importSourceHierarchyQuiet();
 update('Importing historical WIR records (unverified)...');
 await importSourceWIRQuiet();
 let done=0;
 for(let phase of Object.keys(sourceArchive.design.phases)){
   let d=sourceArchive.design.phases[phase],raw=atob(sourceArchive.ngl.ph[phase]||''),valid=raw.length===d.e.length*2;
   for(let offset=0;offset<d.e.length;offset+=1000){
     let rows=[];
     for(let i=offset;i<Math.min(offset+1000,d.e.length);i++){
       let code=valid?(raw.charCodeAt(2*i)|(raw.charCodeAt(2*i+1)<<8)):65535;
       rows.push({id:'alom-grid-'+activeProject+'-'+phase+'-'+i,projectId:activeProject,pointNo:'IFC-'+phase+'-'+String(i+1).padStart(6,'0'),easting:sourceArchive.design.E0+d.e[i]/10,northing:sourceArchive.design.N0+d.n_[i]/10,designRL:sourceArchive.design.Z0+d.z[i]/1000,nglRL:code===65535?null:sourceArchive.ngl.z0+code*sourceArchive.ngl.u,phase,phaseId:'alom-phase-'+activeProject+'-'+phase,zoneId:'',areaId:'',sourceIndex:i,source:'ALOMA​​IER IFC',originalPointNoAvailable:false});
     }
     await batchPut('points',rows);done+=rows.length;
     update('Imported '+done.toLocaleString()+' / '+expected.toLocaleString()+' IFC points. Keep this page open.');
     await new Promise(resolve=>setTimeout(resolve,0));
   }
 }
 update('Imported '+done.toLocaleString()+' IFC points. Refreshing database...');
 await reload();
 toast('Original archive imported: '+done.toLocaleString()+' IFC points');const auto=$('atlasAutoStatus');if(auto)auto.textContent='Archive ready: '+done.toLocaleString()+' IFC points. Historical WIRs remain unverified.';
 }catch(e){update('Import stopped after partial progress: '+e.message+'. Re-run to resume; IDs are stable.');toast(e.message)}
 finally{if(btn)btn.disabled=false}
}
async function importSourceHierarchyQuiet(){let a=sourceArchive,ps=Object.keys(a.design.phases).map(p=>({id:'alom-phase-'+activeProject+'-'+p,projectId:activeProject,name:'Phase '+p.slice(1),code:p,source:'ALOMA​​IER'}));await batchPut('phases',ps);let zones=[...new Set(a.areas.map(x=>x.zone))].map(z=>({id:'alom-zone-'+activeProject+'-'+z.replace(/[^a-zA-Z0-9]/g,'_'),projectId:activeProject,phaseId:ps[0].id,name:z,code:z,source:'ALOMA​​IER',phaseAssignmentUnverified:true}));await batchPut('zones',zones);await batchPut('areas',a.areas.map(ar=>({id:'alom-area-'+activeProject+'-'+ar.k,projectId:activeProject,zoneId:'alom-zone-'+activeProject+'-'+ar.zone.replace(/[^a-zA-Z0-9]/g,'_'),name:ar.name,code:ar.k,boundary:JSON.stringify(ar.c),source:'ALOMA​​IER',sourceAreaM2:ar.m2})))}
async function importSourceWIRQuiet(){await batchPut('wirs',sourceArchive.wirs.map(w=>({id:'alom-wir-'+activeProject+'-'+w.cno,projectId:activeProject,reference:w.cno,date:w.date,layer:Number(w.layer)||0,status:'IMPORTED_UNVERIFIED',remarks:w.desc||'',source:'ALOMA​​IER',sourcePhase:w.phase,sourceRef:w.ref,sourceObservations:w.pts||[]})))}

function bindPhase5(){let allBtn=$('sourceAll');if(allBtn)allBtn.onclick=importAllSourceData;let pc=$('progressCSV');if(pc)pc.onclick=()=>{let areas=scoped('areas'),pts=scoped('points'),sv=scoped('surveys');download('area_progress.csv',toCSV([['Area','Total Points','Valid RL Points','Latest Accepted Surveys','Final Layer Verified'],...areas.map(a=>{let ps=pts.filter(p=>p.areaId===a.id);return [a.name,ps.length,ps.filter(p=>Number.isFinite(p.designRL)&&Number.isFinite(p.nglRL)).length,ps.filter(p=>SurveyOps.latestAccepted(sv,p.id)).length,ps.filter(p=>{let x=SurveyOps.progress(p,sv,layerSettings);return x.rows.length&&x.completed===x.rows.length}).length]})]),'text/csv')};let load=$('sourceLoad');if(!load)return;load.onclick=async()=>{try{let response=await fetch('./alomaier-source.json');if(!response.ok)throw Error('Archive fetch failed ('+response.status+')');sourceArchive=await response.json();render();toast('Original archive loaded')}catch(e){toast('Serve the full PWA folder via HTTPS or localhost. '+e.message)}};let h=$('sourceAreas');if(h)h.onclick=async()=>{if(!sourceArchive)return;try{if(!confirm('Import original phases, zones and areas into the active project? Source zone-to-phase mapping needs manual verification.'))return;await importSourceHierarchy()}catch(e){toast(e.message)}};let w=$('sourceWirs');if(w)w.onclick=async()=>{if(!sourceArchive)return;try{if(!confirm('Import all historical WIRs as IMPORTED_UNVERIFIED? Existing records with same source reference will be updated.'))return;await importSourceWIR()}catch(e){toast(e.message)}};let form=$('sourceGridForm'),preview=$('gridSourcePreview');if(preview)preview.onclick=()=>{try{if(!sourceArchive)throw Error('Load archive first');let v=Object.fromEntries(new FormData(form)),x=decodeSourceGrid(v.phase,Number(v.offset),Math.min(10,Number(v.size)));$('gridSourceResults').innerHTML=`<p class="muted">Phase total: ${x.total} · NGL encoding ${x.valid?'valid':'invalid; missing NGL'}</p><div class="tablewrap"><table><thead><tr><th>Reference</th><th>Easting</th><th>Northing</th><th>Design RL</th><th>NGL RL</th></tr></thead><tbody>${x.rows.map(p=>`<tr><td>${p.pointNo}</td><td>${num(p.easting)}</td><td>${num(p.northing)}</td><td>${num(p.designRL)}</td><td>${p.nglRL===null?'Missing':num(p.nglRL)}</td></tr>`).join('')}</tbody></table></div>`}catch(e){toast(e.message)}};if(form)form.onsubmit=async e=>{e.preventDefault();try{if(!sourceArchive||!activeProject)throw Error('Load archive and select a project');let v=Object.fromEntries(new FormData(form)),offset=Number(v.offset),count=Number(v.size);if(!Number.isInteger(offset)||offset<0||count>2000)throw Error('Invalid batch');let x=decodeSourceGrid(v.phase,offset,count);if(!confirm('Import '+x.rows.length+' source IFC points? Generated references are not original point numbers.'))return;await batchPut('points',x.rows.map(p=>({...p,id:'alom-grid-'+activeProject+'-'+p.phase+'-'+p.sourceIndex,projectId:activeProject,phaseId:'alom-phase-'+activeProject+'-'+p.phase,zoneId:'',areaId:'',source:'ALOMA​​IER IFC',originalPointNoAvailable:false})));await reload();toast('Imported '+x.rows.length+' IFC grid points')}catch(e){toast(e.message)}}}


let matchTolerance=1,matchResults=null,matchPhase='P1',matchLimit=1000;
function matchingPage(){let n=sourceArchive?.wirs?.reduce((v,w)=>v+(w.pts?.length||0),0)||0;return `<div class="grid">${section('Historical Survey ↔ IFC Coordinate Audit',`<p class="note">This is a <b>read-only candidate matching audit</b>. Historical WIR point numbers are not assumed to equal IFC generated IDs. Candidate matching uses Easting/Northing distance, not point-number equality. No surveys are approved, no points are overwritten and no quantities are modified.</p><div class="actions"><button class="btn gold" id="matchLoad">Load Original Archive</button><button class="btn" id="matchRun" ${!sourceArchive?'disabled':''}>Run Matching Audit</button><button class="btn" id="matchExport" ${!matchResults?'disabled':''}>Export Audit CSV</button></div><div class="form"><label>IFC Phase<select id="matchPhase">${['P1','P2','P3','P4'].map(x=>`<option ${matchPhase===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Coordinate Tolerance (m)<input id="matchTolerance" type="number" min="0.01" max="10" step=".01" value="${matchTolerance}"></label><label>Maximum WIR Observations<select id="matchLimit">${[100,1000,5000,20000].map(x=>`<option value="${x}" ${matchLimit===x?'selected':''}>${x.toLocaleString()}</option>`).join('')}</select></label></div><p class="muted small">Source archive: ${sourceArchive?'loaded':'not loaded'} · Historical observations: ${n.toLocaleString()} · IFC phase: ${matchPhase}. Preview is limited to 200 audit rows.</p><div id="matchResults">${matchResults?renderMatchResults():empty('Load archive, choose a phase and run audit.')}</div>`,'wide')}</div>`}
function renderMatchResults(){let rows=matchResults||[],counts={};for(let x of rows)counts[x.status]=(counts[x.status]||0)+1;return `<div class="grid">${metric('Audited Observations',rows.length,'Selected batch')}${metric('Candidate',counts.CANDIDATE||0,'Requires manual confirmation')}${metric('Ambiguous',counts.AMBIGUOUS||0,'Multiple nearby IFC points')}${metric('No Match',counts.NO_MATCH||0,'No point within tolerance')}</div><div class="tablewrap"><table><thead><tr><th>WIR</th><th>Original Point No</th><th>Easting</th><th>Northing</th><th>Nearest IFC</th><th>Distance m</th><th>Result</th></tr></thead><tbody>${rows.slice(0,200).map(x=>`<tr><td>${esc(x.wir)}</td><td>${esc(x.originalNo)}</td><td>${num(x.easting)}</td><td>${num(x.northing)}</td><td>${esc(x.nearestId)}</td><td>${x.nearestDistance===null?'—':x.nearestDistance.toFixed(3)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`}
function bindPhase6(){let load=$('matchLoad');if(!load)return;load.onclick=async()=>{try{let response=await fetch('./alomaier-source.json');if(!response.ok)throw Error('Archive not available');sourceArchive=await response.json();matchResults=null;render();toast('Archive loaded for matching audit')}catch(e){toast('Load from HTTPS or localhost: '+e.message)}};$('matchPhase').onchange=e=>{matchPhase=e.target.value;matchResults=null;render()};$('matchRun').onclick=()=>{try{if(!sourceArchive)throw Error('Load archive first');matchTolerance=Number($('matchTolerance').value);matchLimit=Number($('matchLimit').value);if(!Number.isFinite(matchTolerance)||matchTolerance<.01||matchTolerance>10)throw Error('Tolerance must be 0.01–10 metres');let d=decodeSourceGrid(matchPhase,0,sourceArchive.design.phases[matchPhase].e.length);let obs=[];for(let w of sourceArchive.wirs){for(let pt of w.pts||[]){if(obs.length>=matchLimit)break;let n=Number(pt[1]),e=Number(pt[2]);if(!Number.isFinite(n)||!Number.isFinite(e))continue;obs.push({wir:w.cno,originalNo:String(pt[0]),northing:n,easting:e,sourceValues:pt.slice(3)})}if(obs.length>=matchLimit)break}matchResults=PointMatch.audit(obs,d.rows,matchTolerance);render();toast('Audit complete. Candidates are not automatically linked.')}catch(e){toast(e.message)}};$('matchExport').onclick=()=>{if(!matchResults)return;download('alomaier_coordinate_match_audit.csv',toCSV([['WIR','Original Point No','Easting','Northing','Candidate IFC Reference','Distance m','Candidates Within Tolerance','Status','IFC Design RL','IFC NGL RL'],...matchResults.map(x=>[x.wir,x.originalNo,x.easting,x.northing,x.nearestId,x.nearestDistance??'',x.candidateCount,x.status,x.designRL??'',x.nglRL??''])]),'text/csv')}}


let reconcileQuery='',reconcileLimit=100;
function linkCandidates(){return (matchResults||[]).filter(x=>x.status==='CANDIDATE'&&x.nearestId&&Number.isFinite(x.nearestDistance))}
function reconcilePage(){let links=scoped('pointlinks'),pts=scoped('points'),surveys=scoped('surveys'),cand=linkCandidates();let records=links.map(l=>{let p=pts.find(x=>x.pointNo===l.ifcReference),a=p?SurveyOps.latestAccepted(surveys,p.id):null;return {...l,point:p,accepted:a,designDelta:a&&p&&Number.isFinite(p.designRL)?a.actualRL-p.designRL:null}});let filtered=records.filter(l=>!reconcileQuery||[l.originalNo,l.ifcReference,l.wir].some(v=>String(v||'').toLowerCase().includes(reconcileQuery.toLowerCase())));return `<div class="grid">${metric('Manually Confirmed Links',links.length,'Local project links')}${metric('With Imported IFC Point',records.filter(x=>x.point).length,'Master point present')}${metric('With Accepted Actual RL',records.filter(x=>x.accepted).length,'Manually recorded status')}${metric('Missing IFC / Survey',records.filter(x=>!x.point||!x.accepted).length,'Needs investigation')}${section('Manual Candidate Confirmation',`<p class="note">Run <b>Source Point Audit</b> first to create candidate matches, then review individual coordinates and explicitly confirm. Only unique candidates are offered. Linking does NOT create an accepted survey, alter Design/NGL, or certify quantities.</p><div class="actions"><button class="btn" data-go="matching">Go to Source Point Audit</button><button class="btn" id="linkExport">Export Link & RL Audit CSV</button></div><p class="muted small">Available candidates from last audit: ${cand.length}. Audit candidates are session-only; confirmed links persist in IndexedDB.</p>${cand.length?`<div class="tablewrap"><table><thead><tr><th>WIR</th><th>Original No</th><th>Candidate IFC</th><th>Distance</th><th>Action</th></tr></thead><tbody>${cand.slice(0,50).map((x,i)=>`<tr><td>${esc(x.wir)}</td><td>${esc(x.originalNo)}</td><td>${esc(x.nearestId)}</td><td>${x.nearestDistance.toFixed(3)} m</td><td><button class="link" data-link="${i}">Review & Confirm</button></td></tr>`).join('')}</tbody></table></div><p class="muted small">First 50 candidates displayed. Increase audit batch or export the complete audit CSV for review.</p>`:empty('No session candidates. Open Source Point Audit and run matching first.')}`,'wide')}${section('Confirmed Links — Actual RL vs Design RL',`<label>Search linked WIR, Original No or IFC Reference<input id="reconcileSearch" value="${esc(reconcileQuery)}" placeholder="Search"></label><p class="note">RL delta = latest manually ACCEPTED Actual RL − Design RL. This is a point-level elevation check, NOT cut/fill volume or independent WIR approval.</p><div class="tablewrap"><table><thead><tr><th>WIR</th><th>Original Point</th><th>IFC Reference</th><th>Match m</th><th>Design RL</th><th>NGL RL</th><th>Accepted Actual RL</th><th>Δ RL (m)</th><th>Action</th></tr></thead><tbody>${filtered.slice(0,reconcileLimit).map(l=>`<tr><td>${esc(l.wir)}</td><td>${esc(l.originalNo)}</td><td>${esc(l.ifcReference)}</td><td>${num(l.distance)}</td><td>${l.point&&Number.isFinite(l.point.designRL)?num(l.point.designRL):'—'}</td><td>${l.point&&Number.isFinite(l.point.nglRL)?num(l.point.nglRL):'—'}</td><td>${l.accepted?num(l.accepted.actualRL):'—'}</td><td>${l.designDelta===null?'—':num(l.designDelta)}</td><td><button class="link" data-unlink="${esc(l.id)}">Unlink</button></td></tr>`).join('')}</tbody></table></div><p class="muted small">Showing ${Math.min(filtered.length,reconcileLimit)} of ${filtered.length}. CSV includes all confirmed links.</p>`,'wide')}</div>`}
function bindPhase7(){let sr=$('reconcileSearch');if(!sr)return;sr.onchange=e=>{reconcileQuery=e.target.value;render()};document.querySelectorAll('[data-link]').forEach(b=>b.onclick=async()=>{let x=linkCandidates()[Number(b.dataset.link)];if(!x)return;let existing=scoped('pointlinks').find(l=>l.wir===x.wir&&l.originalNo===x.originalNo);if(existing)return toast('This WIR observation already has a confirmed link');let p=scoped('points').find(v=>v.pointNo===x.nearestId);let message=`Confirm candidate link?\nWIR: ${x.wir}\nOriginal point: ${x.originalNo}\nCandidate IFC: ${x.nearestId}\nDistance: ${x.nearestDistance.toFixed(3)} m\nE: ${x.easting} / N: ${x.northing}\nMaster IFC point: ${p?'imported':'not imported'}\n\nThis is a manual coordinate link, not QA approval.`;if(!confirm(message))return;await put('pointlinks',{id:id(),projectId:activeProject,wir:x.wir,originalNo:x.originalNo,ifcReference:x.nearestId,distance:x.nearestDistance,easting:x.easting,northing:x.northing,phase:matchPhase,confirmedAt:new Date().toISOString(),status:'MANUAL_COORDINATE_LINK'});await reload();toast('Manual link saved')});document.querySelectorAll('[data-unlink]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this manual link? Original WIR and master point data remain unchanged.'))return;await del('pointlinks',b.dataset.unlink);await reload();toast('Link removed')});$('linkExport').onclick=()=>{let rows=scoped('pointlinks').map(l=>{let p=scoped('points').find(v=>v.pointNo===l.ifcReference),a=p?SurveyOps.latestAccepted(scoped('surveys'),p.id):null;return [l.wir,l.originalNo,l.ifcReference,l.distance,l.phase,l.confirmedAt,p?.designRL??'',p?.nglRL??'',a?.actualRL??'',a&&Number.isFinite(p?.designRL)?a.actualRL-p.designRL:'',p?'YES':'NO']});download('confirmed_point_links_rl_audit.csv',toCSV([['WIR','Original Point','IFC Reference','Match Distance m','IFC Phase','Confirmed At','Design RL','NGL RL','Latest Accepted Actual RL','Actual minus Design RL','IFC Imported'],...rows]),'text/csv')}}


let qaSpacing=10,qaArea='',qaResult=null;
function qaSummary(area,pts,surveys,spacing){let ps=pts.filter(p=>p.areaId===area.id),accepted=surveys.filter(s=>s.status==='ACCEPTED'),latest=new Map();for(let s of accepted){let old=latest.get(s.pointId);if(!old||(s.date||'')>(old.date||'')||((s.date||'')===(old.date||'')&&(s.createdAt||'')>(old.createdAt||'')))latest.set(s.pointId,s)}let mapped=ps.filter(p=>latest.has(p.id)&&Number.isFinite(latest.get(p.id).actualRL));let boundary=Array.isArray(area.boundary)?area.boundary:parseBoundarySafe(area);if(boundary.length<3)throw Error('Area has no valid boundary corners');let design=SherazEngineering.evaluateArea({boundary},ps,spacing);let actual=SherazEngineering.evaluateArea({boundary},mapped.map(p=>({...p,nglRL:latest.get(p.id).actualRL})),spacing);let surveyedArea=actual.coveredArea;let designArea=design.coveredArea;return {area,points:ps.length,acceptedPoints:mapped.length,design,actual,surveyedArea,designArea,remainingFill:actual.fill,overDesign:actual.cut,coverage:design.boundaryArea?designArea/design.boundaryArea:0,surveyCoverage:design.boundaryArea?surveyedArea/design.boundaryArea:0,quality:design.overlap?'OVERLAP':design.coverageRatio<.98?'INCOMPLETE GRID':design.missing?'MISSING NGL':'REVIEW REQUIRED'}}
function qualityPage(){let areas=scoped('areas');return `<div class="grid">${section('Area-wise Quantity Reconciliation & Survey Quality',`<p class="note">Engineering preview. Original NGL-to-Design quantities and accepted Actual-RL-to-Design differences are reported separately. <b>Actual RL is not substituted for NGL in the baseline calculation.</b> This is not certified as-built volume, compaction acceptance, or measured progress. Survey coverage and cell overlap must be reviewed.</p><form id="qaForm" class="form"><label>Area<select name="areaId" required>${selectOptions(areas,'Select Area',qaArea)}</select></label><label>Nominal Cell Spacing (m)<input name="spacing" type="number" step="any" min="0.01" max="1000" value="${qaSpacing}" required></label><div class="actions"><button class="btn gold">Run Quality & Quantity Audit</button><button class="btn" type="button" id="qaExport" ${qaResult?'':'disabled'}>Export Point QA CSV</button></div></form><div id="qaResults">${qaResult?qaResultHTML(qaResult):empty('Select an area and calculate. Accepted surveys are required for actual RL comparison.')}</div>`,'wide')}${section('Quality Rules',`<p class="muted">Baseline requires area-assigned points with valid Design and NGL. Actual comparison requires a manually ACCEPTED survey linked to the same master point. Missing surveys are excluded, not assumed complete. Area coverage is based on clipped nominal cells and can be incomplete or overlapping.</p><p class="muted">The result is a diagnostic snapshot; it does not write to original archive, WIR or master elevations.</p>`,'wide')}</div>`}
function qaResultHTML(x){let pct=v=>Math.round(v*1000)/10+'%',warn=[];if(x.design.overlap)warn.push('Nominal cells overlap — quantities may be overstated');if(x.design.coverageRatio<.98)warn.push('Baseline grid does not cover full area');if(x.design.missing)warn.push(x.design.missing+' clipped points have missing NGL / Design');if(x.actual.overlap)warn.push('Surveyed cells overlap');if(x.surveyCoverage<.98)warn.push('Actual RL survey coverage is incomplete');return `<div class="grid" style="margin-top:14px">${metric('Boundary Area',num(x.design.boundaryArea)+' m²','Polygon corners')}${metric('Baseline Cell Coverage',pct(x.coverage),num(x.designArea)+' m²')}${metric('Accepted Survey Coverage',pct(x.surveyCoverage),x.acceptedPoints+' / '+x.points+' points')}${metric('Baseline Fill / Cut',num(x.design.fill)+' / '+num(x.design.cut)+' m³','NGL → Design')}${metric('Actual Below / Above Design',num(x.remainingFill)+' / '+num(x.overDesign)+' m³','Accepted RL → Design; diagnostic')}${metric('QA Flags',warn.length,warn.length?'Review before using':'Still requires engineering validation')}</div><div class="note">${warn.length?warn.map(esc).join(' · '):'No automatic QA flags. Engineer review is still required.'}</div><div class="tablewrap"><table><thead><tr><th>Point</th><th>Clipped Cell m²</th><th>Design − NGL m</th><th>Baseline Fill m³</th><th>Baseline Cut m³</th><th>Accepted RL</th><th>Design − Actual m</th></tr></thead><tbody>${x.design.rows.slice(0,150).map(r=>{let p=scoped('points').find(p=>p.areaId===x.area.id&&p.pointNo===r.pointNo),a=p?SurveyOps.latestAccepted(scoped('surveys'),p.id):null;return `<tr><td>${esc(r.pointNo)}</td><td>${num(r.cellArea)}</td><td>${r.depth===null?'—':num(r.depth)}</td><td>${r.fill===null?'—':num(r.fill)}</td><td>${r.cut===null?'—':num(r.cut)}</td><td>${a?num(a.actualRL):'—'}</td><td>${a&&p&&Number.isFinite(p.designRL)?num(p.designRL-a.actualRL):'—'}</td></tr>`}).join('')}</tbody></table></div><p class="small muted">Showing up to 150 baseline points. Export CSV for all evaluated points.</p>`}
function bindPhase8(){let f=$('qaForm');if(!f)return;f.onsubmit=e=>{e.preventDefault();try{let v=Object.fromEntries(new FormData(f));qaArea=v.areaId;qaSpacing=Number(v.spacing);if(!(qaSpacing>0&&qaSpacing<=1000))throw Error('Invalid spacing');let a=ref('areas',qaArea);if(!a||a.projectId!==activeProject)throw Error('Choose a valid area');qaResult=qaSummary(a,scoped('points'),scoped('surveys'),qaSpacing);render();toast('Diagnostic audit calculated')}catch(e){toast(e.message)}};$('qaExport').onclick=()=>{if(!qaResult)return;let x=qaResult;let pts=scoped('points').filter(p=>p.areaId===x.area.id);let lookup=new Map(pts.map(p=>[p.pointNo,p]));download('area_quantity_quality_audit.csv',toCSV([['Area','Point','Clipped Cell m2','Design-NGL m','Baseline Fill m3','Baseline Cut m3','Accepted Actual RL','Design-Actual m','Status'],...x.design.rows.map(r=>{let p=lookup.get(r.pointNo),a=p?SurveyOps.latestAccepted(scoped('surveys'),p.id):null;return [x.area.name,r.pointNo,r.cellArea,r.depth??'',r.fill??'',r.cut??'',a?.actualRL??'',a&&p&&Number.isFinite(p.designRL)?p.designRL-a.actualRL:'',a?'MANUALLY_ACCEPTED':'NO_ACCEPTED_SURVEY']})]),'text/csv')};}


let ganttArea='',ganttMax=15,reportPreparedBy='',reportReviewedBy='';
function ganttStats(){let pts=scoped('points'),surveys=scoped('surveys'),areas=scoped('areas');let a=areas.find(x=>x.id===ganttArea),ps=a?pts.filter(p=>p.areaId===a.id):pts.filter(p=>p.areaId);let eligible=ps.filter(p=>typeof p.nglRL==='number'&&Number.isFinite(p.nglRL)&&typeof p.designRL==='number'&&Number.isFinite(p.designRL));let plans=eligible.map(p=>({p,r:SurveyOps.progress(p,surveys,layerSettings)})).filter(x=>!x.r.error&&x.r.rows.length);let layers=Array.from({length:30},(_,i)=>{let l=i+1,planned=plans.filter(x=>x.r.rows.length>=l),done=planned.filter(x=>x.r.accepted&&x.r.accepted.actualRL>=x.r.rows[l-1].targetRL-layerSettings.tolerance);return {layer:l,planned:planned.length,done:done.length,percent:planned.length?100*done.length/planned.length:0}});let accepted=plans.filter(x=>x.r.accepted).length,completed=plans.filter(x=>x.r.completed===x.r.rows.length).length;return {a,ps,eligible,plans,layers,accepted,completed}}
function ganttPage(){let d=ganttStats(),ar=scoped('areas'),n=Math.min(30,Math.max(1,ganttMax));return `<div class="grid">${section('Area Layer Matrix / Gantt-style Progress',`<div class="actions"><label>Area <select id="ganttArea"><option value="">All assigned areas</option>${ar.map(a=>`<option value="${esc(a.id)}" ${a.id===ganttArea?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Display Layers <select id="ganttCount">${[5,10,15,20,30].map(x=>`<option ${x===ganttMax?'selected':''}>${x}</option>`).join('')}</select></label><button class="btn gold" id="ganttPrint">Print / Save PDF</button><button class="btn" id="ganttExport">Export Layer CSV</button></div><p class="note">This is a layer completion matrix, not a calendar-based construction schedule. Planned counts come from NGL/Design RL and configured layer thickness; completed counts use latest manually ACCEPTED survey elevations. No approval is inferred from historical WIR records.</p><div id="ganttPrintable" class="reportPaper"><h2>${esc(current()?.name||'Project')} — Layer Progress Report</h2><p class="muted">Area: ${esc(d.a?.name||'All assigned areas')} · Generated: ${new Date().toLocaleDateString()} · Thickness: ${layerSettings.thickness} m · Preparation: ${layerSettings.preparation} m</p><div class="grid">${metric('Points in Scope',d.ps.length,'Area-assigned grading points')}${metric('Eligible Layer Plans',d.plans.length,'Valid NGL and Design')}${metric('Accepted Survey Points',d.accepted,'Manually recorded')}${metric('Final Layer Reached',d.completed,'Point count, not volume')}</div><div class="tablewrap"><table class="ganttTable"><thead><tr><th>Layer</th><th>Planned Points</th><th>Reached Points</th><th>Completion</th><th>Progress Bar</th></tr></thead><tbody>${d.layers.slice(0,n).map(l=>`<tr><td>${l.layer}</td><td>${l.planned}</td><td>${l.done}</td><td>${l.planned?l.percent.toFixed(1)+'%':'N/A'}</td><td><div class="progressTrack"><span style="width:${l.percent}%"></span></div></td></tr>`).join('')}</tbody></table></div><p class="muted small">Prepared by: ${esc(reportPreparedBy||'________________')} · Reviewed by: ${esc(reportReviewedBy||'________________')}</p></div>`,'wide')}${section('Report Sign-off',`<div class="form"><label>Prepared By<input id="reportPrepared" value="${esc(reportPreparedBy)}" placeholder="Survey Engineer"></label><label>Reviewed By<input id="reportReviewed" value="${esc(reportReviewedBy)}" placeholder="QA/QC or Consultant"></label></div><p class="note">Names are report annotations, not electronic signatures or verified approvals. Use browser Print → Save as PDF to produce a PDF copy.</p>`,'wide')}</div>`}
function executivePage(){let pts=scoped('points'),areas=scoped('areas'),surveys=scoped('surveys'),wirs=scoped('wirs'),links=scoped('pointlinks'),accepted=surveys.filter(x=>x.status==='ACCEPTED'),pending=surveys.filter(x=>x.status==='PENDING'),rejected=surveys.filter(x=>x.status==='REJECTED'),eligible=pts.filter(p=>typeof p.nglRL==='number'&&Number.isFinite(p.nglRL)&&typeof p.designRL==='number'&&Number.isFinite(p.designRL)),completed=eligible.filter(p=>{let x=SurveyOps.progress(p,surveys,layerSettings);return !x.error&&x.rows.length>0&&x.completed===x.rows.length}).length,missing=pts.length-eligible.length;let group=areas.map(a=>{let ps=eligible.filter(p=>p.areaId===a.id),done=ps.filter(p=>{let x=SurveyOps.progress(p,surveys,layerSettings);return !x.error&&x.rows.length&&x.completed===x.rows.length}).length;return {a,count:ps.length,done,percent:ps.length?Math.round(100*done/ps.length):0}});return `<div class="grid">${section('Executive Project Status',`<div class="actions"><button class="btn gold" id="executivePrint">Print / Save PDF</button><button class="btn" id="executiveCSV">Export Summary CSV</button></div><div id="executivePrintable" class="reportPaper"><h2>${esc(current()?.name||'No project selected')} — Project Management Summary</h2><p class="muted">Project Code: ${esc(current()?.code||'—')} · Generated: ${new Date().toLocaleDateString()}</p><div class="grid">${metric('Master Points',pts.length,'Imported and manually entered')}${metric('Project Areas',areas.length,'Registered area boundaries')}${metric('RL Complete',eligible.length,'Design + NGL present')}${metric('Missing RL',missing,'Needs QA review')}${metric('Survey Records',surveys.length,'All recorded statuses')}${metric('Accepted Observations',accepted.length,'Manually recorded')}${metric('Pending / Rejected',pending.length+' / '+rejected.length,'QA workflow')}${metric('Historical / Current WIRs',wirs.length,'Status not externally verified')}${metric('Manual IFC Links',links.length,'Coordinate matching links')}${metric('Final Layer Reached',completed,'Of '+eligible.length+' RL-complete points')}</div><h3>Area Completion Overview</h3><div class="tablewrap"><table><thead><tr><th>Area</th><th>Eligible Points</th><th>Final Layer Reached</th><th>Point Completion</th></tr></thead><tbody>${group.map(x=>`<tr><td>${esc(x.a.name)}</td><td>${x.count}</td><td>${x.done}</td><td>${x.count?x.percent+'%':'N/A'}</td></tr>`).join('')}</tbody></table></div><p class="note">Progress is based on manually ACCEPTED survey elevations and point counts, not measured volumes or certified construction progress. WIR statuses and manual IFC links are not independently verified. Missing data remains missing.</p></div>`,'wide')}</div>`}
function bindPhase9(){let ga=$('ganttArea');if(ga){ga.onchange=e=>{ganttArea=e.target.value;render()};$('ganttCount').onchange=e=>{ganttMax=Number(e.target.value);render()};$('ganttPrint').onclick=()=>window.print();$('reportPrepared').onchange=e=>{reportPreparedBy=e.target.value;render()};$('reportReviewed').onchange=e=>{reportReviewedBy=e.target.value;render()};$('ganttExport').onclick=()=>{let d=ganttStats();download('layer_progress_matrix.csv',toCSV([['Area','Layer','Planned Points','Reached Points','Completion Percent','Definition'],...d.layers.map(l=>[d.a?.name||'All assigned areas',l.layer,l.planned,l.done,l.planned?l.percent.toFixed(2):'', 'Manual ACCEPTED survey RL >= layer target - tolerance'])]),'text/csv')}}let ep=$('executivePrint');if(ep){ep.onclick=()=>window.print();$('executiveCSV').onclick=()=>{let d=ganttStats();download('executive_area_summary.csv',toCSV([['Area','Eligible Points','Final Layer Reached','Point Completion Percent'],...scoped('areas').map(a=>{let p=scoped('points').filter(x=>x.areaId===a.id&&Number.isFinite(x.nglRL)&&Number.isFinite(x.designRL));let done=p.filter(x=>{let q=SurveyOps.progress(x,scoped('surveys'),layerSettings);return !q.error&&q.rows.length&&q.completed===q.rows.length}).length;return [a.name,p.length,done,p.length?(100*done/p.length).toFixed(2):'']} )]),'text/csv')}}}


let qa10Limit=200,qa10Findings=[];
function audit10Data(){let pts=scoped('points'),areas=scoped('areas'),surveys=scoped('surveys'),wirs=scoped('wirs'),links=scoped('pointlinks'),phases=scoped('phases'),zones=scoped('zones');let findings=[],add=(severity,category,reference,detail)=>findings.push({severity,category,reference:String(reference??''),detail});let pointIDs=new Set(pts.map(p=>p.id)),areaIDs=new Set(areas.map(a=>a.id)),phaseIDs=new Set(phases.map(p=>p.id)),zoneIDs=new Set(zones.map(z=>z.id));let seen=new Set();for(let p of pts){let name=String(p.pointNo||'').trim().toLowerCase();if(!name)add('ERROR','Point',p.id,'Missing point number');else if(seen.has(name))add('ERROR','Point',p.pointNo,'Duplicate point number in project');else seen.add(name);if(!Number.isFinite(p.easting)||!Number.isFinite(p.northing))add('ERROR','Coordinates',p.pointNo,'Invalid Easting or Northing');if(!Number.isFinite(p.designRL))add('ERROR','Elevation',p.pointNo,'Missing/invalid Design RL');if(!Number.isFinite(p.nglRL))add('WARN','Elevation',p.pointNo,'Missing/invalid NGL RL');if(p.areaId&&!areaIDs.has(p.areaId))add('ERROR','Hierarchy',p.pointNo,'Area reference does not exist');if(p.zoneId&&!zoneIDs.has(p.zoneId))add('ERROR','Hierarchy',p.pointNo,'Zone reference does not exist');if(p.phaseId&&!phaseIDs.has(p.phaseId))add('ERROR','Hierarchy',p.pointNo,'Phase reference does not exist')}
for(let a of areas){let b=parseBoundarySafe(a);if(b.length<3)add('WARN','Area',a.name,'Fewer than 3 valid boundary corners');else{let polyArea=Math.abs(b.reduce((sum,v,i)=>{let next=b[(i+1)%b.length];return sum+v[0]*next[1]-next[0]*v[1]},0))/2;if(polyArea<.001)add('ERROR','Area',a.name,'Zero or nearly zero boundary area');if(b.length>3){for(let i=0;i<b.length;i++)for(let j=i+1;j<b.length;j++){if(Math.abs(i-j)<=1||(i===0&&j===b.length-1))continue;let x=b[i],y=b[(i+1)%b.length],u=b[j],v=b[(j+1)%b.length];let cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);let d1=cross(x,y,u),d2=cross(x,y,v),d3=cross(u,v,x),d4=cross(u,v,y);if(d1*d2<0&&d3*d4<0){add('ERROR','Area',a.name,'Self-intersecting boundary');i=b.length;break}}}}if(a.zoneId&&!zoneIDs.has(a.zoneId))add('ERROR','Hierarchy',a.name,'Area zone reference does not exist')}
for(let x of surveys){if(!pointIDs.has(x.pointId))add('ERROR','Survey',x.id,'Survey references missing grading point');if(!Number.isFinite(x.actualRL))add('ERROR','Survey',x.id,'Invalid actual RL');if(!['ACCEPTED','REJECTED','PENDING'].includes(x.status))add('WARN','Survey',x.id,'Unknown survey status')}
for(let x of links){let target=x.pointId||x.ifcPointId||x.masterPointId;if(target&&!pointIDs.has(target))add('WARN','Point Link',x.id,'Linked point not in local Master Points')}
return {findings,stats:{points:pts.length,areas:areas.length,surveys:surveys.length,wirs:wirs.length,links:links.length},errors:findings.filter(x=>x.severity==='ERROR').length,warnings:findings.filter(x=>x.severity==='WARN').length}}
function audit10Page(){let q=audit10Data();qa10Findings=q.findings;return `<div class="grid">${metric('Master Points',num(q.stats.points),'Current project')}${metric('Integrity Errors',num(q.errors),'Fix before relying on reports')}${metric('Review Warnings',num(q.warnings),'Missing or questionable data')}${metric('Survey / WIR',num(q.stats.surveys)+' / '+num(q.stats.wirs),'Recorded observations')}${section('Data Integrity & Release 10 QA',`<p class="note">This audit checks local data consistency, orphan references, duplicate point numbers, missing elevations, and basic polygon validity. It does not certify survey measurements, approval status, or engineering volumes.</p><div class="actions"><button class="btn gold" id="qa10Refresh">Re-run Audit</button><button class="btn" id="qa10CSV">Export Full QA Findings CSV</button><button class="btn" id="qa10Backup">Download Safety Backup</button></div><p class="muted small">Showing first ${Math.min(qa10Limit,q.findings.length).toLocaleString()} of ${q.findings.length.toLocaleString()} findings. CSV includes all findings.</p><div class="tablewrap"><table><thead><tr><th>Severity</th><th>Category</th><th>Reference</th><th>Finding</th></tr></thead><tbody>${q.findings.slice(0,qa10Limit).map(f=>`<tr><td>${esc(f.severity)}</td><td>${esc(f.category)}</td><td>${esc(f.reference)}</td><td>${esc(f.detail)}</td></tr>`).join('')}</tbody></table></div>${q.findings.length?'':'<p class="note">No issues detected by these automated checks. Field verification is still required.</p>'}`,'wide')}${section('Performance & Safety',`<p>IFC imports use a single IndexedDB batch transaction for each selected batch, and internal record lookups are cached between reloads. For large datasets, import in 100–2,000-point batches and export a JSON backup regularly.</p><p class="muted small">Offline support requires HTTPS or localhost. Browser storage is local to this device. No cloud synchronization, multi-user locking, or independent field certification is included.</p>`,'wide')}</div>`}
function bindPhase10(){if(page!=='audit10')return;$('qa10Refresh').onclick=()=>render();$('qa10CSV').onclick=()=>download('data_integrity_audit.csv',toCSV([['Severity','Category','Reference','Finding'],...qa10Findings.map(f=>[f.severity,f.category,f.reference,f.detail])]),'text/csv');$('qa10Backup').onclick=()=>download('sheraz_safety_backup_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({format:'sheraz-survey-foundation',version:1,exportedAt:new Date().toISOString(),data:state}), 'application/json')}

async function initializeAtlasArchive(){
 try{
  const r=await fetch('./alomaier-source.json');if(!r.ok)throw Error('Original archive missing');
  sourceArchive=await r.json();
  const archiveProjectId='eng-sheraz-atlas-alomaier';
  let project=await get('projects',archiveProjectId);
  if(!project){await put('projects',{id:archiveProjectId,name:'ALOMA​​IER Earthwork Project',code:'ALOMA​​IER',createdAt:new Date().toISOString(),source:'ALOMA​​IER'});}
  activeProject=archiveProjectId;
  await reload();
  const existing=state.points.filter(p=>p.projectId===archiveProjectId && String(p.id).startsWith('alom-grid-')).length;
  const expected=Object.values(sourceArchive.design.phases).reduce((n,p)=>n+p.e.length,0);
  if(existing<expected){
    const banner=$('atlasAutoStatus');if(banner)banner.textContent='Preparing original IFC archive: '+existing.toLocaleString()+' / '+expected.toLocaleString()+' points. Keep this page open.';
    await importAllSourceData(true);
  }else{
    const banner=$('atlasAutoStatus');if(banner)banner.textContent='Original archive ready: '+existing.toLocaleString()+' IFC points. Historical WIRs are unverified.';
  }
 }catch(err){const banner=$('atlasAutoStatus');if(banner)banner.textContent='Archive auto-setup unavailable: '+err.message+' — use Alomaier Migration to retry.';console.error(err)}
}
$('nav').onclick=e=>{let b=e.target.closest('[data-page]');if(b){page=b.dataset.page;render()}};$('projectSelect').onchange=e=>{activeProject=e.target.value;render()};window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false});$('install').onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('install').hidden=true}};if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});openDB().then(async d=>{db=d;await reload();await initializeAtlasArchive()}).catch(e=>{$('view').innerHTML='<div class="card dangertext">IndexedDB could not be opened. Use a modern browser and allow local storage. '+esc(e.message)+'</div>'});
